	@Test
	void concurrentEntryBoundComputedAggregatesRemainIndependentAndParallel() throws Exception {
		set("rdf4j.lmdb.nativeQueryEngine.enabled", "false");
		set("rdf4j.lmdb.janinoCodegen.enabled", "false");
		set("rdf4j.lmdb.parallel.enabled", "false");
		set(LmdbNativeParallelKernelAggregate.ENABLED_PROPERTY, "false");
		List<BindingSet> expectedLeft = rowsForPrefix(LEFT_PREFIX);
		List<BindingSet> expectedRight = rowsForPrefix(RIGHT_PREFIX);
		assertThat(expectedLeft).as("generic left result must contain one group per value").hasSize(VALUE_COUNT);
		assertThat(expectedRight).as("generic right result must contain one group per value").hasSize(VALUE_COUNT);
		assertThat(expectedLeft).doesNotContainAnyElementsOf(expectedRight);

		set("rdf4j.lmdb.nativeQueryEngine.enabled", "true");
		set("rdf4j.lmdb.janinoCodegen.enabled", "true");
		set("rdf4j.lmdb.parallel.enabled", "true");
		set(LmdbNativeParallelKernelAggregate.ENABLED_PROPERTY, "true");
		long parallelRunsBefore = LmdbNativeParallelKernelAggregate.PARALLEL_RUNS.get();

		CountDownLatch queriesReady = new CountDownLatch(2);
		CountDownLatch rightRowsReady = new CountDownLatch(1);
		CountDownLatch leftConnectionClosed = new CountDownLatch(1);
		AtomicInteger activeQueries = new AtomicInteger();
		AtomicInteger maximumActiveQueries = new AtomicInteger();
		ExecutorService executor = new ThreadPoolExecutor(2, 2, 0L, TimeUnit.MILLISECONDS,
				new ArrayBlockingQueue<>(2));
		Future<Evaluation> left = executor.submit(() -> evaluateWithLifetime(LEFT_PREFIX, true, queriesReady,
				rightRowsReady, leftConnectionClosed, activeQueries, maximumActiveQueries));
		Future<Evaluation> right = executor.submit(() -> evaluateWithLifetime(RIGHT_PREFIX, false, queriesReady,
				rightRowsReady, leftConnectionClosed, activeQueries, maximumActiveQueries));
		try {
			Evaluation actualLeft = left.get(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS);
			Evaluation actualRight = right.get(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS);

			assertThat(actualLeft.rows()).as("left complete bindings must match the generic evaluator")
					.containsExactlyInAnyOrderElementsOf(expectedLeft);
			assertThat(actualRight.rows()).as("right complete bindings must match the generic evaluator")
					.containsExactlyInAnyOrderElementsOf(expectedRight);
			assertThat(actualLeft.keys()).as("left values must retain the left query scope after close")
					.allMatch(value -> value.stringValue().startsWith(LEFT_PREFIX + ":"));
			assertThat(actualLeft.keys()).noneMatch(value -> value.stringValue().startsWith(RIGHT_PREFIX + ":"));
			assertThat(actualRight.keys()).as("right values must survive the other connection closing")
					.allMatch(value -> value.stringValue().startsWith(RIGHT_PREFIX + ":"));
			assertThat(actualRight.keys()).noneMatch(value -> value.stringValue().startsWith(LEFT_PREFIX + ":"));
			assertThat(maximumActiveQueries).as("both public evaluations must overlap").hasValue(2);
		} finally {
			executor.shutdownNow();
			assertThat(executor.awaitTermination(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS))
					.as("query executor must terminate after the two evaluations")
					.isTrue();
		}

		assertThat(LmdbNativeParallelKernelAggregate.PARALLEL_RUNS.get() - parallelRunsBefore)
				.as("both entry-bound computed aggregates must complete through the parallel aggregate rung")
				.isGreaterThanOrEqualTo(2);
	}

	private Evaluation evaluateWithLifetime(String prefix, boolean closesFirst, CountDownLatch queriesReady,
			CountDownLatch rightRowsReady, CountDownLatch leftConnectionClosed, AtomicInteger activeQueries,
			AtomicInteger maximumActiveQueries) {
		int active = activeQueries.incrementAndGet();
		maximumActiveQueries.accumulateAndGet(active, Math::max);
		try {
			if (closesFirst) {
				List<BindingSet> rows;
				try (SailRepositoryConnection connection = repository.getConnection()) {
					SailTupleQuery query = prepare(connection, prefix, true);
					queriesReady.countDown();
					awaitTogether(queriesReady);
					try (TupleQueryResult result = query.evaluate()) {
						rows = new ArrayList<>();
						consumeFirst(result, rows, prefix);
						awaitTogether(rightRowsReady);
						drain(result, rows);
					}
				} finally {
					// The signal is deliberately after the try-with-resources block: the other task reads its held RDF
					// values only after this task has closed both its result and its connection.
					leftConnectionClosed.countDown();
				}
				return snapshot(rows);
			}

			try (SailRepositoryConnection connection = repository.getConnection()) {
				SailTupleQuery query = prepare(connection, prefix, true);
				queriesReady.countDown();
				awaitTogether(queriesReady);
				List<BindingSet> rows = new ArrayList<>();
				try (TupleQueryResult result = query.evaluate()) {
					consumeFirst(result, rows, prefix);
					rightRowsReady.countDown();
					awaitTogether(leftConnectionClosed);
					// The first row has been retained while the other task closes its result and connection. The
					// remaining
					// rows are consumed only after that close, exercising both the value and cursor lifetime boundary.
					drain(result, rows);
				}
				// This conversion happens after the other query closes its connection while this query's first value is
				// still retained, exercising the lifetime boundary rather than only comparing row counts.
				return snapshot(rows);
			}
		} finally {
			activeQueries.decrementAndGet();
		}
	}

	private SailTupleQuery prepare(SailRepositoryConnection connection, String prefix, boolean forceAggregate) {
		SailTupleQuery query = (SailTupleQuery) connection.prepareTupleQuery(QUERY);
		query.setBinding("prefix", connection.getValueFactory().createLiteral(prefix));
		if (forceAggregate) {
			query.setForcedLmdbExecutionStrategy(LmdbNativeAttemptMetrics.PATH_IR_AGGREGATE_PARALLEL);
		}
		return query;
	}

	private List<BindingSet> rowsForPrefix(String prefix) {
		try (SailRepositoryConnection connection = repository.getConnection()) {
			return materialize(prepare(connection, prefix, false));
		}
	}

	private static List<BindingSet> materialize(SailTupleQuery query) {
		try (TupleQueryResult result = query.evaluate()) {
			List<BindingSet> rows = new ArrayList<>();
			drain(result, rows);
			return rows;
		}
	}

	private static void consumeFirst(TupleQueryResult result, List<BindingSet> rows, String prefix) {
		if (!result.hasNext()) {
			throw new AssertionError("the " + prefix + " computed aggregate returned no first row");
		}
		rows.add(result.next());
	}

	private static void drain(TupleQueryResult result, List<BindingSet> rows) {
		while (result.hasNext()) {
			rows.add(result.next());
		}
	}

	private static Evaluation snapshot(List<BindingSet> rows) {
		List<Value> keys = new ArrayList<>(rows.size());
		for (BindingSet row : rows) {
			keys.add(row.getValue("key"));
		}
		return new Evaluation(List.copyOf(rows), List.copyOf(keys));
	}

	private static void awaitTogether(CountDownLatch latch) {
		try {
			if (!latch.await(LATCH_TIMEOUT_SECONDS, TimeUnit.SECONDS)) {
				throw new AssertionError("latch timed out");
			}
		} catch (InterruptedException failure) {
			Thread.currentThread().interrupt();
			throw new AssertionError(failure);
		}
	}

	private void set(String property, String value) {
		System.setProperty(property, value);
	}

	private record Evaluation(List<BindingSet> rows, List<Value> keys) {
	}
